/**
 * UV coordinates in normalized -2 to 2 range (vec2).
 * At edge of quad: UV = ±2.0, so dot(UV,UV) = 4.0 (2-sigma boundary).
 *
 * @type {Node}
 */
export const gaussianUV: Node;
/**
 * Splat color from SH evaluation (vec4: rgba).
 * Contains pre-computed spherical harmonics color.
 *
 * @type {Node}
 */
export const gaussianColor: Node;
/**
 * NDC depth value in [0,1] range (float).
 * Pre-computed in vertex shader for perfect sync with scene depth.
 * 0 = near plane, 1 = far plane.
 * Unpacked from vPackedData.z.
 *
 * @type {Node}
 */
export const gaussianDepth: Node;
/**
 * View-space normal from 3D Gaussian ellipsoid (vec3).
 * Computed from the smallest scale axis (flattest direction).
 * Pre-flipped to face camera in compute shader.
 *
 * @type {Node}
 */
export const gaussianNormal: Node;
/**
 * Opacity-weighted normal that blends true 3D normal with view-aligned normal.
 * Reduces z-fighting noise at splat edges where overlapping splats flicker.
 *
 * - At splat center (high alpha): uses true 3D normal from ellipsoid
 * - At splat edge (low alpha): fades to stable view-aligned normal
 *
 * This eliminates flickering since z-fighting happens most at low-alpha edges.
 *
 * @type {Node}
 */
/**
 * Anti-aliasing compensation factor (float).
 * Compensates alpha for intensity reduction from low-pass filtering.
 * Unpacked from vPackedData.y.
 *
 * @type {Node}
 */
export const gaussianAAFactor: Node;
/**
 * Visibility flag (float: 0 or 1).
 * Set by compute shader based on culling.
 * Unpacked from vPackedData.x.
 *
 * @type {Node}
 */
export const gaussianVisible: Node;
/**
 * Full RGB Spherical Harmonics contribution (vec3).
 * View-dependent color delta from base DC color.
 * Used by material to apply shStrength: finalColor = baseColor + shColor * shStrength
 *
 * @type {Node}
 * @example
 * // Visualize SH contribution as RGB
 * material.emissiveNode = gaussianSHColor.mul(2.0).add(0.5); // Map to visible range
 * // Or use with custom strength
 * const adjusted = gaussianSHColor.mul(shStrengthUniform);
 */
export const gaussianSHColor: Node;
/**
 * World position of the splat center (vec3).
 * Computed from model matrix * local position in compute shader.
 * Used for shadow receiving - represents the actual 3D location of the Gaussian.
 *
 * @type {Node}
 */
export const gaussianWorldPosition: Node;
/**
 * Morton index normalized to [0,1] range (float).
 * With Morton ordering: spatially-adjacent splats have similar indices.
 * Use with mortonDebugColor() to visualize spatial locality.
 *
 * @type {Node}
 */
export const gaussianMortonIdx: Node;
/**
 * Splat index (uint as float for varying compatibility).
 * Used for tile-based culling to verify splat membership in tiles.
 *
 * @type {Node}
 */
export const gaussianSplatIdx: Node;
/**
 * Generate rainbow color from Morton index for debug visualization.
 * Maps normalized index [0,1] to HSV rainbow (hue 0-1, saturation 1, value 1).
 *
 * **Interpretation:**
 * - Smooth color gradients = good Morton ordering (spatially-adjacent splats have similar colors)
 * - Random color noise = poor/no ordering (cache thrashing likely)
 *
 * @param {Node} idx - Normalized Morton index [0,1]
 * @returns {Node.<vec3>} RGB color
 */
export const mortonDebugColor: any;
/**
 * Spherical Harmonics contribution magnitude (float).
 * Computed as length of gaussianSHColor.
 * Use this to visualize where and how strongly SH affects the rendering.
 *
 * @type {Node}
 * @example
 * // Visualize SH contribution as grayscale
 * material.emissiveNode = vec3(gaussianSH);
 */
export const gaussianSH: Node;
/**
 * Compute Gaussian alpha falloff using UV coordinates.
 * Uses SuperSplat's normalized exponential formula for clean quad edges.
 *
 * Formula: (exp(-4*A) - EXP4) * INV_EXP4
 * - At center (A=0): alpha = 1.0
 * - At edge (A=1): alpha = 0.0
 *
 * This normalization ensures zero alpha at quad boundaries, preventing
 * visible edges and ensuring smooth blending between overlapping splats.
 *
 * @param {Node} uv - UV coordinates in [-1, 1] range (vec2)
 * @returns {Node} Gaussian alpha (0 to 1)
 * @example
 * const alpha = gaussianAlphaUV(gaussianUV);
 */
export const gaussianAlphaUV: any;
/**
 * Compute final opacity combining Gaussian, base alpha, and AA factor.
 *
 * @param {Node} uv - UV coordinates
 * @param {Node} falloff - Gaussian falloff strength
 * @param {Node} baseAlpha - Base splat opacity
 * @param {Node} aaFactor - Anti-aliasing compensation
 * @returns {Node} Final clamped opacity (max 0.99)
 */
export const gaussianOpacity: any;
/**
 * Interleaved Gradient Noise for dithered transparency.
 * Uses IGN algorithm for high-quality stochastic patterns.
 *
 * @param {Node} fragCoord - Screen coordinates (vec2)
 * @returns {Node} Noise value (0 to 1)
 */
export const gaussianDitherNoise: any;
/**
 * Compute luminance from RGB color using standard coefficients.
 *
 * @param {Node} color - RGB color (vec3)
 * @returns {Node} Luminance value (0 to 1)
 */
export const gaussianLuminance: any;
/**
 * Extract hue from RGB color and map to RGB wheel for visualization.
 *
 * @param {Node} color - RGB color (vec3)
 * @returns {Node} Hue as RGB color (vec3)
 */
export const gaussianHue: any;
/**
 * Compute Gaussian power (exponent) and normalize to 0-1.
 * Returns 1 at center, 0 at edge (inverted for visualization).
 *
 * @param {Node} uv - UV coordinates
 * @returns {Node} Normalized power (1 at center, 0 at edge)
 */
export const gaussianPower: any;
/**
 * Apply exposure adjustment (brightness multiplier).
 * Works best on linear color values.
 *
 * @param {Node} color - RGB color (vec3)
 * @param {Node} exposure - Exposure multiplier (typically 0.1-3.0)
 * @returns {Node} Adjusted color (vec3)
 */
export const applyExposure: any;
/**
 * Apply contrast adjustment around midpoint.
 * Expands or compresses tonal range around 0.5.
 *
 * @param {Node} color - RGB color (vec3)
 * @param {Node} contrast - Contrast multiplier (0.5 = flat, 1.0 = normal, 2.0 = high)
 * @returns {Node} Adjusted color (vec3)
 */
export const applyContrast: any;
/**
 * Apply saturation adjustment using luminance.
 * Uses Rec.709 luminance coefficients.
 *
 * @param {Node} color - RGB color (vec3)
 * @param {Node} saturation - Saturation (0 = grayscale, 1 = normal, 2 = oversaturated)
 * @returns {Node} Adjusted color (vec3)
 */
export const applySaturation: any;
/**
 * Apply vibrance (selective saturation).
 * Affects unsaturated colors more than already-saturated colors.
 * Useful for boosting muted tones without oversaturating vibrant areas.
 *
 * @param {Node} color - RGB color (vec3)
 * @param {Node} vibrance - Vibrance amount (-1 to 1, 0 = no change)
 * @returns {Node} Adjusted color (vec3)
 */
export const applyVibrance: any;
/**
 * Apply highlight and shadow adjustment (lift/gain style).
 * Shadows affect dark values, highlights affect bright values.
 * Uses soft quadratic falloff for smooth transitions.
 *
 * @param {Node} color - RGB color (vec3)
 * @param {Node} highlights - Highlight adjustment (-1 to 1)
 * @param {Node} shadows - Shadow adjustment (-1 to 1)
 * @returns {Node} Adjusted color (vec3)
 */
export const applyHighlightsShadows: any;
